  ('editors_picks', 'Editor''s Picks', 'Hand-selected literary monuments chosen by Welton Academy curators.', 1),
  ('new_additions', 'New Additions', 'Freshly catalogued volumes, recent editions, and rediscovered gems.', 2),
  ('classics', 'Classics', 'Time-tested works that have haunted cloisters and libraries for centuries.', 3),
