INSERT INTO public.works (id, legacy_code, title, description, first_published_year, benchmark_rating, benchmark_review_count, featured_quote_text, featured_quote_speaker, is_club_select) VALUES
  ('1adf1d09-65fe-5899-90e2-ecb3d558be9f', 'b1', 'The Secret History', 'Under the influence of their charismatic classics professor, a group of clever, eccentric misfits at an elite New England college discover a way of thinking and living that is a world away from the humdrum existence of their contemporaries. But when they go beyond the boundaries of normal morality they slip gradually from obsession to corruption and betrayal, and - ultimately - to evil.', 1992, 4.8, 1420, 'Beauty is terror. Whatever we call beautiful, we quiver before it.', 'Julian Morrow', true),
  ('8d3afe56-812b-5e6f-b320-19f65179df2a', 'b2', 'Dead Poets Society', 'Todd Anderson and his friends at Welton Academy can hardly believe how different life is since their new English teacher, John Keating, arrived. Passionate about teaching, Keating encourages his students to make their lives extraordinary — to seize the day and suck the marrow out of life.', 1989, 4.9, 2150, 'No matter what anybody tells you, words and ideas can change the world.', 'John Keating', true),
  ('1d8d3659-0eec-5f7a-ace2-78487b517cd7', 'b3', 'The Picture of Dorian Gray', 'Enthralled by his own exquisite portrait, Dorian Gray trades his soul for eternal youth and beauty. While he pursues a hedonistic lifestyle of sensation and vice in Victorian London, only the hidden portrait ages, bearing the scars of his sins.', 1890, 4.6, 3200, 'Those who find ugly meanings in beautiful things are corrupt without being charming. This is a fault.', 'Oscar Wilde', true),
  ('d2f87dd2-254d-5893-939c-93b4a9623792', 'b4', 'If We Were Villains', 'On the day Oliver Marks is released from prison after ten years, he is met by the detective who put him there. Detective Colborne is retiring, but before he does, he wants to know what really happened ten years ago at Dellecher Classical Conservatory.', 2017, 4.5, 980, 'For someone who loved words as much as I did, it was embarrassing how rarely they did what I wanted.', 'Oliver Marks', false),
  ('58d0db33-cd5f-599b-b1bb-cc772b16d45b', 'b5', 'Frankenstein', 'Victor Frankenstein, an idealistic Geneva student, discovers the secret of imparting life to inanimate matter. Horrified by the unnatural creature he brings forth, he abandons it, initiating a tragic cycle of vengeance, loneliness, and despair across Europe.', 1818, 4.7, 4100, 'Beware; for I am fearless, and therefore powerful.', 'The Creature', true),
  ('3bcc5f6c-7886-550c-8456-19fd293162fb', 'b6', 'Babel: An Arcane History', 'Oxford, 1828. The Royal Institute of Translation—known as Babel—is the world’s center for translation and magic. Robin Swift finds himself caught between his devotion to scholarship and an inevitable betrayal of his homeland.', 2022, 4.6, 850, 'Translation is always a betrayal of the original.', 'Professor Richard Lovell', true),
  ('d5218e31-b0b9-533b-8b18-a4fc613e4714', 'b7', 'Wuthering Heights', 'A tempestuous tale of passionate and destructive love between Heathcliff, a wild foundling, and Catherine Earnshaw, set against the desolate Yorkshire moors.', 1847, 4.4, 3800, 'Whatever our souls are made of, his and mine are the same.', 'Catherine Earnshaw', false),
  ('b8574503-acdf-5e30-aa36-55768c62cf44', 'b8', 'Piranesi', 'Piranesi lives in the House. Perhaps he always has. In his notebooks day after day he makes a meticulous record of its wonders: the labyrinth of halls, the thousands upon thousands of statues, the tides surging up staircases.', 2020, 4.7, 1650, 'The Beauty of the House is immeasurable; its Kindness infinite.', 'Piranesi', false),
  ('49ad98eb-6f71-50c9-876d-de8893a59b80', 'b9', 'Jane Eyre', 'The story of an orphaned young woman who maintains her fierce independence and integrity while working as a governess at Thornfield Hall and falling in love with the brooding Mr. Rochester.', 1847, 4.8, 4500, 'I am no bird; and no net ensnares me; I am a free human being with an independent will.', 'Jane Eyre', false),
  ('4d881fee-473f-5beb-9d56-5d46333abf60', 'b10', 'Dracula', 'Told through journal entries, letters, and telegraphs, Jonathan Harker travels to Transylvania to aid Count Dracula in purchasing an estate in London, unaware of the ancient terror he is awakening.', 1897, 4.5, 2900, 'Listen to them, the children of the night. What music they make!', 'Count Dracula', false),
  ('9f258ee2-a598-5293-a833-f67ebda6b5ec', 'b11', 'The Bell Jar', 'Chronicles the breakdown of Esther Greenwood: brilliant, beautiful, enormously talented, and successful, but slowly going under—maybe for the last time.', 1963, 4.5, 2400, 'I took a deep breath and listened to the old brag of my heart: I am, I am, I am.', 'Esther Greenwood', true),
  ('8b5ea10c-8b13-56d4-81cc-96cbdb193bef', 'b12', 'The Song of Achilles', 'A breathtaking reimagining of Homer’s Iliad from the perspective of Patroclus, an exiled young prince who bonds deeply with the glorious warrior Achilles.', 2011, 4.8, 3600, 'He is half of my soul, as the poets say.', 'Patroclus', false),
  ('67005871-728b-5fee-8a33-cca78b6b518f', 'b13', 'Crime and Punishment', 'Raskolnikov, an impoverished student living in Saint Petersburg, formulates a theory of extraordinary beings exempt from moral laws, and acts upon it with catastrophic consequences.', 1866, 4.7, 3100, 'Pain and suffering are always inevitable for a large intelligence and a deep heart.', 'Rodion Raskolnikov', false),
  ('b474cd52-d25f-5653-bf32-10c670d3dc12', 'b14', 'The Shadow of the Wind', 'Barcelona, 1945: Daniel Sempere is taken to the secret Cemetery of Forgotten Books to choose a volume. The book he selects pulls him into an enigmatic spiral of passion, murder, and cursed history.', 2001, 4.9, 2200, 'Every book has two souls: the soul of the person who wrote it and the soul of the reader who read it.', 'Daniel Sempere', false),
  ('2d21ee0a-a6aa-5214-b672-aea3a2ccc07c', 'b15', 'Rebecca', 'A young companion marries the wealthy widower Maxim de Winter and arrives at Manderley, only to find the isolated estate haunted by the pervasive memory of his deceased first wife, Rebecca.', 1938, 4.6, 2750, 'Last night I dreamt I went to Manderley again.', 'Narrator', false),
  ('2380ac2b-7e7e-5a15-8867-94e64db6aac0', 'b16', 'The Goldfinch', 'Theo Decker, a 13-year-old New Yorker, miraculously survives an accident that kills his mother. In his grief, he clings to a small, mysteriously captivating painting that ultimately draws him into the art underworld.', 2013, 4.5, 1890, 'Caring too much for objects can destroy you. Only - if you care for a thing enough, it takes on a life of its own.', 'Theo Decker', false),
  ('64983913-c2d7-5dc6-b437-c23fed93da21', 'b17', 'Never Let Me Go', 'Kathy, Ruth, and Tommy grow up at Hailsham, an idyllic English boarding school harboring an unspoken, chilling secret regarding their true purpose in society.', 2005, 4.6, 2300, 'I keep thinking about this river somewhere, with the water moving really fast. And these two people in the water...', 'Kathy H.', false),
  ('26406dad-13bf-54dd-8bba-0fd65aea8343', 'b18', 'The Starless Sea', 'Zachary Ezra Rawlins is a graduate student in Vermont when he discovers a mysterious book hidden in the library stacks—a book that turns out to contain a story from his own childhood.', 2019, 4.4, 1450, 'We are all stardust and stories.', 'Mirabel', false),
  ('b2a9170c-a8bc-5f0b-a5f3-13f6e868c457', 'b19', 'Bunny', 'Samantha Heather Mackey is an outsider in her small, highly selective MFA writing program at New England’s Warren University, until she is invited into the inner sanctum of the sinister clique known as the Bunnies.', 2019, 4.3, 1120, 'We call each other Bunny because we are so soft and sweet and harmless.', 'The Bunnies', false),
  ('57ce9591-b0d1-5a89-b5ba-e7129818434d', 'b20', 'Hamnet', 'A luminous portrait of a marriage, a devastating grief, and the forgotten boy whose name was given to one of the most celebrated plays in human history.', 2020, 4.7, 1780, 'Every life has its own kernel of mystery.', 'Agnes Hathaway', false),
  ('74d03f65-3e71-5128-8da7-ac14d359c11c', 'b21', 'The Metamorphosis', 'One morning, when Gregor Samsa woke from troubled dreams, he found himself transformed in his bed into a horrible vermin.', 1915, 4.5, 3400, 'I cannot make you understand. I cannot make anyone understand what is happening inside me.', 'Gregor Samsa', false),
  ('211bce8b-581d-58b8-99c7-b61cd2e23cb6', 'b22', 'Pride and Prejudice', 'The romantic clash between the opinionated Elizabeth Bennet and her proud, enigmatic suitor, Fitzwilliam Darcy, in early 19th-century England.', 1813, 4.9, 5200, 'You have bewitched me, body and soul, and I love, I love, I love you.', 'Mr. Darcy', false),
  ('2db480a6-f23b-584c-9985-6788b00ffb08', 'b23', 'Northanger Abbey', 'Catherine Morland, an innocent young woman obsessed with gothic horror novels, travels to Bath and begins imagining ominous murders within an ancient abbey.', 1817, 4.3, 1400, 'The person, be it gentleman or lady, who has not pleasure in a good novel, must be intolerably stupid.', 'Henry Tilney', false),
  ('6b1ddf8a-f8aa-51a1-b848-3bbcdf2f91aa', 'b24', 'Emma', 'Handsome, clever, and rich, Emma Woodhouse is convinced she is a brilliant matchmaker, until her misjudgments threaten the happiness of those around her.', 1815, 4.6, 2800, 'If I loved you less, I might be able to talk about it more.', 'Mr. Knightley', false),
  ('8d280651-b812-5616-957e-016f6b97b5eb', 'b25', 'Leaves of Grass', 'Whitman’s landmark celebration of nature, democracy, spirituality, the human body, and the boundless American soul.', 1855, 4.7, 1200, 'I celebrate myself, and sing myself, and what I assume you shall assume.', 'Walt Whitman', false),
  ('d09dd04c-71b4-567f-98a4-30949f200c40', 'b26', 'Les Misérables', 'Jean Valjean, an ex-convict seeking redemption, becomes a savior and father figure in 19th-century France while relentlessly pursued by Inspector Javert.', 1862, 4.8, 3100, 'To love or have loved, that is enough. Ask nothing further. There is no other pearl to be found in the dark folds of life.', 'Victor Hugo', false),
  ('8b8f3c2c-a2c4-57a1-b160-0452b0f0aca7', 'b27', 'The Count of Monte Cristo', 'Edmond Dantès is falsely accused of treason and imprisoned in the sinister Château d''If. Fourteen years later, he escapes, acquires a vast fortune, and sets out to execute vengeance.', 1844, 4.9, 4900, 'All human wisdom is contained in these two words: Wait and Hope.', 'Edmond Dantès', false),
  ('50db63a8-7420-5d03-b0ec-a7e7d5f7e945', 'b28', '1984', 'Winston Smith struggles to maintain his sanity and individualism under the omnipresent, terrifying surveillance of Big Brother and the Party in Oceania.', 1949, 4.7, 6500, 'Perhaps one did not want to be loved so much as to be understood.', 'Winston Smith', false),
  ('e4d573a5-1d14-5769-a8f3-5504dacbab12', 'b29', 'Little Women', 'The heartwarming, beloved story of four sisters—Meg, Jo, Beth, and Amy March—growing up in Civil War-era Massachusetts.', 1868, 4.6, 3900, 'I''d rather take coffee than compliments just now.', 'Amy March', false),
  ('645f8e0c-77bf-5c5b-8ca4-f975f8edf6be', 'b30', 'The Catcher in the Rye', 'Sixteen-year-old Holden Caulfield navigates New York City after being expelled from prep school, meditating on phoniness, innocence, and vulnerability.', 1951, 4.2, 3100, 'I like it when somebody gets excited about something. It''s nice.', 'Holden Caulfield', false),
  ('3a164e94-d02a-5e73-a328-31dd419ef975', 'b31', 'Norwegian Wood', 'Toru Watanabe looks back on his student days in Tokyo during the late 1960s, caught between his devotion to the fragile, grieving Naoko and his irresistible attraction to the fiercely independent Midori.', 1987, 4.6, 3100, 'Death exists, not as the opposite but as a part of life.', 'Toru Watanabe', true),
  ('410f0168-1843-59ef-8aab-9d0bf8b1331d', 'b32', 'The Stranger', 'Through the story of Meursault, who will not lie to himself or to society, Camus elucidates his philosophy of the Absurd and the alienating absurdity of human existence.', 1942, 4.5, 4200, 'In the midst of winter, I found there was, within me, an invincible summer.', 'Albert Camus', false),
  ('73ce5af5-ed2d-5f28-af74-0058362a807b', 'b33', 'To the Lighthouse', 'A landmark exploration of time, art, and grief centred around the Ramsay family’s visits to the Isle of Skye, where the elusive beam of the lighthouse measures the quiet passage of mortal years.', 1927, 4.5, 2800, 'What is the meaning of life? That was all—a simple question that tended to close in on one with years.', 'Lily Briscoe', true),
  ('a8dc4157-aa0f-5ae7-8674-d70822f63630', 'b34', 'Letters to a Young Poet', 'Ten intimate letters from poet Rainer Maria Rilke to a young military cadet wrestling with the decision to become a writer, offering enduring wisdom on loneliness, creativity, and love.', 1929, 4.8, 3100, 'Let life happen to you. Believe me: life is right, at any rate.', 'Rainer Maria Rilke', true)
